examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
private struct Conversation {
    let subject: String
    let from: String
    let preview: String
}

private let conversations = [
    Conversation(subject: {{conversations.0.subject}}, from: {{conversations.0.from}}, preview: {{conversations.0.preview}}),
    Conversation(subject: {{conversations.1.subject}}, from: {{conversations.1.from}}, preview: {{conversations.1.preview}}),
    Conversation(subject: {{conversations.2.subject}}, from: {{conversations.2.from}}, preview: {{conversations.2.preview}}),
]
@State private var selection = {{selected}}
@State private var showsContext = false

private var list: some View {
    ScrollView {
        VStack(alignment: .leading, spacing: theme.spacing.space1) {
            ForEach(Array(conversations.enumerated()), id: \.offset) { index, conversation in
                Button { selection = index } label: {
                    VStack(alignment: .leading, spacing: theme.spacing.space0_5) {
                        Text(conversation.subject).monarchTextStyle(.label)
                        Text(conversation.from + " \u{00B7} " + conversation.preview)
                            .monarchTextStyle(.caption)
                            .foregroundStyle(theme.colors.textMuted)
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(theme.spacing.space2)
                    .background(
                        selection == index ? theme.colors.accentSubtle : Color.clear,
                        in: RoundedRectangle(cornerRadius: 8, style: .continuous)
                    )
                }
                .buttonStyle(.plain)
                .accessibilityAddTraits(selection == index ? .isSelected : [])
            }
        }
        .padding(theme.spacing.space2)
    }
}

private var conversation: some View {
    VStack(alignment: .leading, spacing: theme.spacing.space2) {
        HStack(alignment: .top, spacing: theme.spacing.space2) {
            Text(conversations[selection].subject).monarchTextStyle(.subheading)
            Spacer(minLength: 0)
            Button { showsContext.toggle() } label: {
                MonarchIcon(systemName: "rectangle.split.3x1", size: .sm)
                    .foregroundStyle(theme.colors.textDefault)
            }
            .accessibilityLabel(showsContext ? "Hide ticket details" : "Show ticket details")
            .frame(minWidth: 44, minHeight: 44, alignment: .topTrailing)
        }
        MonarchBadge({{status.label}}, tone: {{status.tone|tone}})
        Text("From " + conversations[selection].from)
            .monarchTextStyle(.bodySmall)
            .foregroundStyle(theme.colors.textMuted)
        Text(conversations[selection].preview).monarchTextStyle(.bodySmall)
        if showsContext {
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                LabeledContent("Requester", value: conversations[selection].from)
                LabeledContent("Priority", value: {{priority}})
                LabeledContent("Assignee", value: "\u{2014}")
            }
            .labeledContentStyle(.monarch)
        }
        Spacer(minLength: 0)
    }
    .padding(theme.spacing.space3)
}

